-- Ciseaux détaillés : à coller dans la Barre de commande de Roblox Studio, puis Entrée
-- Les ciseaux apparaissent devant ta caméra.

local camCF = workspace.CurrentCamera.CFrame
local dir = Vector3.new(camCF.LookVector.X, 0, camCF.LookVector.Z)
if dir.Magnitude < 0.01 then dir = Vector3.new(0, 0, -1) end
local devant = camCF.Position + dir.Unit * 8
local hit = workspace:Raycast(devant + Vector3.new(0, 50, 0), Vector3.new(0, -500, 0))
local sol = if hit then hit.Position else Vector3.new(devant.X, 0, devant.Z)
local origine = CFrame.lookAt(sol, sol + dir)

local v, M = Vector3.new, Enum.Material
local function cf(...) return CFrame.new(...) end
local C1 = Color3.fromRGB(188, 194, 203)
local C2 = Color3.fromRGB(242, 244, 247)
local C3 = Color3.fromRGB(120, 126, 136)
local C4 = Color3.fromRGB(200, 30, 35)
local C5 = Color3.fromRGB(240, 90, 90)
local C6 = Color3.fromRGB(38, 40, 46)
local C7 = Color3.fromRGB(201, 162, 72)
local C8 = Color3.fromRGB(60, 48, 22)

local modele = Instance.new("Model")
modele.Name = "Ciseaux"

local function dossier(nom, parent)
	local d = Instance.new("Folder")
	d.Name = nom
	d.Parent = parent
	return d
end

local function p(nom, classe, forme, parent, taille, c, couleur, matiere, reflet)
	local part = Instance.new(classe)
	part.Name = nom
	if classe == "Part" then part.Shape = Enum.PartType[forme] end
	part.Size = taille
	part.CFrame = origine * c
	part.Color = couleur
	part.Material = matiere
	part.Reflectance = reflet
	part.Anchored = true
	part.TopSurface = Enum.SurfaceType.Smooth
	part.BottomSurface = Enum.SurfaceType.Smooth
	part.Parent = parent
end

